import { installWorkspace } from '@projexlight/connector-slack';
const { install_id, team_id } = await installWorkspace({
  tenant_id, auth_code,
});

import { postMessage } from '@projexlight/connector-slack';
await postMessage({
  tenant_id, channel: '#ops',
  text: '🚨 Storm declared: Cat-3 hurricane, 4,000 customers in scope',
  blocks: [...],
});

import { handleInteractive } from '@projexlight/connector-slack';
await handleInteractive({
  tenant_id, payload: req.body, // verified by Slack signature
});

import { handleEvent } from '@projexlight/connector-slack';
await handleEvent({
  tenant_id, event: { type: 'message', channel, thread_ts, user, text },
});
